CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK (length(display_name)<=100), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (auth.uid()=id);
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (auth.uid()=id) WITH CHECK (auth.uid()=id);
CREATE FUNCTION public.create_parent_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES (NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),100)); RETURN NEW; END; $$;
CREATE TRIGGER create_parent_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_parent_profile();
CREATE TABLE public.children (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, display_name text NOT NULL CHECK(length(display_name) BETWEEN 1 AND 60), age integer NOT NULL CHECK(age BETWEEN 5 AND 13), preferences jsonb NOT NULL DEFAULT '{}', guardian_consent_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.children TO authenticated;
GRANT ALL ON public.children TO service_role;
ALTER TABLE public.children ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_children ON public.children FOR ALL TO authenticated USING(auth.uid()=parent_id) WITH CHECK(auth.uid()=parent_id);
CREATE INDEX children_parent_idx ON public.children(parent_id);
CREATE TABLE public.learning_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), child_id uuid NOT NULL REFERENCES public.children(id) ON DELETE CASCADE, parent_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, activity_id text NOT NULL CHECK(length(activity_id)<=80), concept text NOT NULL CHECK(length(concept)<=80), event_type text NOT NULL CHECK(event_type IN ('answer','hint','explanation','manipulation','transfer','discovery')), correct boolean, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.learning_events TO authenticated;
GRANT ALL ON public.learning_events TO service_role;
ALTER TABLE public.learning_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_events_read ON public.learning_events FOR SELECT TO authenticated USING(auth.uid()=parent_id);
CREATE POLICY own_events_insert ON public.learning_events FOR INSERT TO authenticated WITH CHECK(auth.uid()=parent_id AND EXISTS(SELECT 1 FROM public.children c WHERE c.id=child_id AND c.parent_id=auth.uid()));
CREATE POLICY own_events_delete ON public.learning_events FOR DELETE TO authenticated USING(auth.uid()=parent_id);
CREATE INDEX learning_events_parent_idx ON public.learning_events(parent_id,created_at);
CREATE TABLE public.support_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, subject text NOT NULL CHECK(length(subject) BETWEEN 1 AND 150), message text NOT NULL CHECK(length(message) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.support_requests TO authenticated;
GRANT ALL ON public.support_requests TO service_role;
ALTER TABLE public.support_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_support ON public.support_requests FOR SELECT TO authenticated USING(auth.uid()=parent_id);
CREATE POLICY create_support ON public.support_requests FOR INSERT TO authenticated WITH CHECK(auth.uid()=parent_id);